 upsert("regional_economy_profiles",{id:"RECO-PDC-"+profile.polity_id,region_id:region,polity_id:profile.polity_id,exports:profile.economy.exports,imports:profile.economy.imports,staples:profile.economy.exports.slice(0,3),risks:profile.pressure,price_pressure:{detail:profile.economy.price_pressures,logic:profile.economy.tax_logic},currency_rule:profile.economy.tax_logic,database_profile_id:profile.id});
 for(const n of profile.npcs)upsert("regional_npc_archetypes",{id:n.id,region_id:region,polity_id:profile.polity_id,culture_id:profile.culture_id,role:n.role,facility_affinity:"guild",social_layer:"政治體資料層固定NPC",knowledge_scope:n.knowledge,quest_domains:["地方政治","區域事件","人物關係"],combat_tier_ceiling:"C",naming_rule:"固定NPC姓名與所在地不可由一般命名器覆蓋。",fixed_name:n.name,location_id:n.location_id,agenda:n.agenda,relationship:n.relationship,knowledge_boundary:{rule:n.knowledge,forbid_global_omniscience:true},database_profile_id:profile.id});
 profile.hooks.forEach((title,i)=>upsert("regional_adventure_hooks",{id:"RAH-PDC-"+profile.polity_id+"-"+(i+1),region_id:region,polity_id:profile.polity_id,kind:i===0?"political":"exploration",title,premise:profile.identity,tier_ceiling:p?.world_tier||"C",history_event_ids:[],organization_ids:p?.key_organization_ids||[],reward_rule:"依實際風險、證物完整度與所在地責任計算，不直接生成超過地區層級的裝備。",state_keys:["political_pressure","local_evidence","regional_cooldown"],database_profile_id:profile.id}));
