 upsert("cultural_festivals",{id:"FEST-PDC-"+profile.polity_id,name:profile.name+"・"+profile.festival.slice(0,8),culture_id:profile.culture_id,region_id:region,season:"依地方曆法",timing:"由政治體資料層與世界日期共同判定",public:true,activities:[profile.festival,profile.culture.ritual,"地方責任與交換儀式"],gameplay_hooks:["政治體專屬NPC密度與對話變化","行省服務、價格與委託來源變化","文化情報與地方事件解鎖"],rule:"節慶只在符合當地季節、政治壓力與供應狀態時生成，不作通用模板。",lore_record_id:null,database_profile_id:profile.id});
